    'templatePrepareQuestionPaperDesc': {'en': 'Please prepare a question paper for the upcoming exam. Include MCQ, short answer, and long answer sections as per the standard pattern.', 'hi': 'कृपया आगामी परीक्षा के लिए प्रश्न पत्र तैयार करें। मानक पैटर्न के अनुसार एमसीक्यू (बहुविकल्पीय प्रश्न), लघु उत्तर और दीर्घ उत्तर अनुभाग शामिल करें।'},
    'templateUpdateSyllabus': {'en': 'Update Syllabus', 'hi': 'पाठ्यक्रम अपडेट करें'},
    'templateUpdateSyllabusDesc': {'en': 'Please update the syllabus completion status in the app for all chapters covered so far this month.', 'hi': 'कृपया इस महीने अब तक कवर किए गए सभी अध्यायों के लिए ऐप में पाठ्यक्रम पूरा होने की स्थिति को अपडेट करें।'},
    'templateDutyAssignment': {'en': 'Duty Assignment', 'hi': 'ड्यूटी आवंटन'},
    'templateDutyAssignmentDesc': {'en': 'You have been assigned duty for the upcoming school event/exam. Please report to your assigned location on time in proper uniform.', 'hi': 'आपको आगामी स्कूल कार्यक्रम/परीक्षा के लिए ड्यूटी सौंपी गई है। कृपया उचित वर्दी में समय पर अपने निर्धारित स्थान पर रिपोर्ट करें।'},
    'templateParentCall': {'en': 'Parent Call', 'hi': 'अभिभावक को कॉल करें'},
    'templateParentCallDesc': {'en': 'Please call the parents of the students listed and update the call status and reason in the Daily Calls section.', 'hi': 'कृपया सूचीबद्ध छात्रों के माता-पिता को कॉल करें और दैनिक कॉल अनुभाग में कॉल की स्थिति और कारण अपडेट करें।'},
    'templatePrepareNotes': {'en': 'Prepare Notes', 'hi': 'नोट्स तैयार करें'},
    'templatePrepareNotesDesc': {'en': 'Please prepare chapter-wise notes for your subject and upload them to the study material section for students.', 'hi': 'कृपया अपने विषय के लिए अध्याय-वार नोट्स तैयार करें और उन्हें छात्रों के लिए अध्ययन सामग्री अनुभाग में अपलोड करें।'},
    'templateAttendanceReport': {'en': 'Attendance Report', 'hi': 'उपस्थिति रिपोर्ट'},
    'templateAttendanceReportDesc': {'en': 'Please review and verify the attendance records for your class for this month and report any discrepancies.', 'hi': 'कृपया इस महीने के लिए अपनी कक्षा के उपस्थिति रिकॉर्ड की समीक्षा और सत्यापन करें और किसी भी विसंगति की रिपोर्ट करें।'},
    'templateMeetingAttendance': {'en': 'Meeting Attendance', 'hi': 'बैठक में उपस्थिति'},
    'templateMeetingAttendanceDesc': {'en': 'Your presence is required at the staff meeting. Please ensure you attend on time and bring any relevant documents.', 'hi': 'कर्मचारी बैठक में आपकी उपस्थिति आवश्यक है। कृपया सुनिश्चित करें कि आप समय पर उपस्थित हों और कोई भी संबंधित दस्तावेज लाएं।'},
